### Telemetry Reporter

The Telemetry Reporter is responsible for emitting request metrics to Prometheus.

```csharp
// TelemetryReporter.cs
using System;
using System.Threading.Tasks;
using Prometheus;

public class TelemetryReporter
{
    private readonly Counter _requestCounter;
    private readonly Histogram _latencyHistogram;

    public TelemetryReporter()
    {
        _requestCounter = Metrics.CreateCounter("requests_total", "Total number of requests");
        _latencyHistogram = Metrics.CreateHistogram("request_latency_seconds", "Request latency in seconds");
    }

    public void EmitRequestMetrics(HttpRequest request, TimeSpan latency)
    {
        _requestCounter.Inc();
        _latencyHistogram.Observe(latency.TotalSeconds);
    }
}
```

**Example Usage**
-----------------

```csharp
// Program.cs
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;

public class Program
{
    public static void Main(string[] args)
    {
        var host = CreateHostBuilder(args).Build();
        host.Run();
    }

    public static IHostBuilder CreateHostBuilder(string[] args) =>
        Host.CreateDefaultBuilder(args)
            .ConfigureWebHostDefaults(webBuilder =>
            {
                webBuilder.UseStartup<Startup>();
            });
}

// Startup.cs
using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddSingleton<InboundTrafficInterceptor>();
        services.AddSingleton<LoadBalancingPolicyEngine>();
        services.AddSingleton<TelemetryReporter>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        app.UseRouting();
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapGet("/", async context =>
            {
                var inboundTrafficInterceptor = context.RequestServices.GetService<InboundTrafficInterceptor>();
                var loadBalancingPolicyEngine = context.RequestServices.GetService<LoadBalancingPolicyEngine>();
                var telemetryReporter = context.RequestServices.GetService<TelemetryReporter>();

                var request = context.Request;
                var decryptedRequestBody = await inboundTrafficInterceptor.DecryptHttpRequestAsync(request);

                var responseMessage = await loadBalancingPolicyEngine.RouteRequestAsync(request);

                telemetryReporter.EmitRequestMetrics(request, TimeSpan.FromMilliseconds(100));

                await context.Response.WriteAsync("Hello, World!");
            });
        });
    }
}
